// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-06.md (шаг 1)
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, form, userIdOf } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Чужой пост по прямой ссылке /post/new?id= — «אפשר לערוך רק פוסט שפרסמת», сохранить нельзя @iphone @prod-safe (#1ff0f4)', async ({ page }) => {
    const me = userIdOf('free');
    try {
      // Предусловие: id поста другого автора — из ответа ленты feed_posts
      const feed = page.waitForResponse((r) => r.url().includes('/rest/v1/feed_posts') && r.request().method() === 'GET');
      await page.goto('/social');
      const rows: Array<{ id: string; author_id: string }> = await (await feed).json();
      const foreign = rows.find((r) => r.author_id && r.author_id !== me);
      expect(foreign, 'в ленте free есть пост другого автора').toBeTruthy();

      // 1. Открыть экран редактирования чужого поста
      await page.goto(`/post/new?id=${foreign!.id}`);
      // Ожидаемо: сообщение, нет поля и «שמירה» (Р1.3)
      await expect(page.getByText('אפשר לערוך רק פוסט שפרסמת')).toBeVisible();
      await expect(form(page).text).toHaveCount(0);
      await expect(form(page).save).toHaveCount(0);
      await expect(form(page).publish).toHaveCount(0);
    } finally {
      await saveSession(page, 'free');
    }
  });
});
